import type { MetadataRoute } from "next";
import { PALETTE } from "@/lib/palette";
import { SITE } from "@/lib/site";

// Colors are the page background from the one palette (lib/palette.ts, dark
// only). Icons are generated by lib/seo/generate-icons.mjs into public/icons/.
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: SITE.name,
    short_name: "Tombstones",
    description: SITE.description,
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: PALETTE.bg,
    theme_color: PALETTE.bg,
    categories: ["travel", "education", "entertainment"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
